package site

import (
	"fmt"
	"regexp"
	"strings"
	"unicode/utf8"
)

// generatedHeader marks every rendered file. A generated file is never edited
// by hand; the header names the source and the command.
const generatedHeader = "<!-- Generated by cmd/gensite from docs/site.json. DO NOT EDIT. -->"

// markdownTokenRE keeps a link or a code span together while wrapping. A link
// may contain spaces, so a plain strings.Fields split would break it.
var markdownTokenRE = regexp.MustCompile("\\[[^\\]]*\\]\\([^)]*\\)[.,;:!?)]*|`[^`]*`[.,;:!?)]*|\\S+")

// docLinks are the destinations inside docs/. A French page is a sibling under
// docs/fr/, so both trees link to the bare file name; a prefix of ../ would
// resolve to the English page one level up.
func (s Site) docLinks() map[string]string {
	out := map[string]string{}
	for _, page := range s.Pages() {
		if page.Nav {
			out[page.Key] = page.DocsName("en")
		}
	}
	return out
}

// readmeLinks are the destinations from the repository root.
func (s Site) readmeLinks(lang string) map[string]string {
	out := map[string]string{}
	for _, page := range s.Pages() {
		if page.Nav {
			out[page.Key] = page.File(lang)
		}
	}
	return out
}

// substitute replaces a {key} placeholder with its destination. Validate
// refuses a source that names a placeholder no renderer supplies.
func substitute(text string, links map[string]string) string {
	pairs := make([]string, 0, len(links)*2)
	for key, href := range links {
		pairs = append(pairs, "{"+key+"}", href)
	}
	return strings.NewReplacer(pairs...).Replace(text)
}

// wrap folds one paragraph at width runes without splitting a link or a code
// span. It preserves no original line breaks: the source is one paragraph per
// value.
func wrap(text string, width int) string {
	tokens := markdownTokenRE.FindAllString(text, -1)
	var out strings.Builder
	line := 0
	for _, token := range tokens {
		size := utf8.RuneCountInString(token)
		switch {
		case line == 0:
			out.WriteString(token)
			line = size
		case line+1+size > width:
			out.WriteString("\n")
			out.WriteString(token)
			line = size
		default:
			out.WriteString(" ")
			out.WriteString(token)
			line += 1 + size
		}
	}
	return out.String()
}

// item renders a list item with a hanging indent.
func item(marker, text string, width int) string {
	body := wrap(text, width-utf8.RuneCountInString(marker))
	return marker + strings.Join(strings.Split(body, "\n"), "\n"+strings.Repeat(" ", utf8.RuneCountInString(marker)))
}

// paragraph appends a wrapped paragraph and one blank line.
func paragraph(out *strings.Builder, text string) {
	out.WriteString(wrap(text, 80))
	out.WriteString("\n\n")
}

// heading appends a level-two heading and one blank line.
func heading(out *strings.Builder, text string) {
	out.WriteString("## ")
	out.WriteString(text)
	out.WriteString("\n\n")
}

// Landing renders docs/index.md or docs/fr/index.md.
func (s Site) Landing(lang string) []byte {
	links := s.docLinks()
	title := s.Hero.Title.For(lang)
	if lang == "fr" {
		title += " (français)"
	}
	var out strings.Builder
	out.WriteString("---\n")
	out.WriteString("layout: default\n")
	fmt.Fprintf(&out, "title: %s\n", title)
	fmt.Fprintf(&out, "lang: %s\n", lang)
	out.WriteString("---\n\n")
	fmt.Fprintf(&out, "# %s\n\n", s.Product)
	paragraph(&out, "**"+s.Hero.Tagline.For(lang)+"**")
	paragraph(&out, s.Hero.Intro.For(lang))
	out.WriteString(s.landingNav(lang))
	out.WriteString("\n\n")
	banner := "assets/banner-en.svg"
	if lang == "fr" {
		banner = "../assets/banner-fr.svg"
	}
	fmt.Fprintf(&out, "![%s](%s)\n\n", s.Product, banner)

	heading(&out, s.Features.Title.For(lang))
	for _, feature := range s.Features.Items {
		text := fmt.Sprintf("**%s** %s", feature.Title.For(lang), feature.Body.For(lang))
		out.WriteString(item("- ", text, 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")

	heading(&out, s.Difference.Title.For(lang))
	paragraph(&out, s.Difference.Body.For(lang))

	heading(&out, s.Runs.Title.For(lang))
	out.WriteString(s.runsTable(lang))
	out.WriteString("\n")
	paragraph(&out, substitute(s.Runs.Note.For(lang), links))

	heading(&out, s.Start.Title.For(lang))
	for index, step := range s.Start.Steps {
		out.WriteString(item(fmt.Sprintf("%d. ", index+1), substitute(step.For(lang), links), 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")

	heading(&out, s.Status.Title.For(lang))
	paragraph(&out, s.Status.Body.For(lang))

	fmt.Fprintf(&out, "[%s](%s) · AGPL-3.0-or-later\n", sourceLabel(lang), s.Repository)
	return []byte(out.String())
}

// Readme renders README.md or README.fr.md.
func (s Site) Readme(lang string) []byte {
	links := s.readmeLinks(lang)
	var out strings.Builder
	out.WriteString(generatedHeader)
	out.WriteString("\n\n")
	fmt.Fprintf(&out, "# %s\n\n", s.Product)
	paragraph(&out, "**"+s.Hero.Tagline.For(lang)+"**")
	paragraph(&out, s.Hero.Intro.For(lang))
	banner := "docs/assets/banner-en.svg"
	if lang == "fr" {
		banner = "docs/assets/banner-fr.svg"
	}
	fmt.Fprintf(&out, "![%s](%s)\n\n", s.Product, banner)
	out.WriteString(s.readmeNav(lang))
	out.WriteString("\n\n")

	heading(&out, s.Features.Title.For(lang))
	for _, feature := range s.Features.Items {
		text := fmt.Sprintf("**%s** %s", feature.Title.For(lang), feature.Body.For(lang))
		out.WriteString(item("- ", text, 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")

	heading(&out, s.Difference.Title.For(lang))
	paragraph(&out, s.Difference.Body.For(lang))

	heading(&out, s.Runs.Title.For(lang))
	out.WriteString(s.runsTable(lang))
	out.WriteString("\n")
	paragraph(&out, substitute(s.Runs.Note.For(lang), links))

	heading(&out, s.Start.Title.For(lang))
	for index, step := range s.Start.Steps {
		out.WriteString(item(fmt.Sprintf("%d. ", index+1), substitute(step.For(lang), links), 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")

	heading(&out, s.Status.Title.For(lang))
	paragraph(&out, s.Status.Body.For(lang))

	heading(&out, s.Build.Title.For(lang))
	paragraph(&out, s.Build.Requirements.For(lang))
	out.WriteString("```bash\n")
	out.WriteString(strings.TrimRight(s.Build.Commands, "\n"))
	out.WriteString("\n```\n\n")
	paragraph(&out, s.Build.Note.For(lang))

	heading(&out, s.License.Title.For(lang))
	paragraph(&out, s.License.Body.For(lang))

	return []byte(strings.TrimRight(out.String(), "\n") + "\n")
}

// landingNav is the language switch plus the public destinations.
func (s Site) landingNav(lang string) string {
	links := s.docLinks()
	parts := []string{languageSwitch(lang, true)}
	for _, item := range s.Nav {
		href, ok := links[item.Key]
		if !ok {
			continue
		}
		parts = append(parts, fmt.Sprintf("[%s](%s)", item.Label.For(lang), href))
	}
	return strings.Join(parts, " · ")
}

// readmeNav is the language switch, the documentation home, and the public
// destinations.
func (s Site) readmeNav(lang string) string {
	links := s.readmeLinks(lang)
	docs := "docs/index.md"
	if lang == "fr" {
		docs = "docs/fr/index.md"
	}
	parts := []string{languageSwitch(lang, false), fmt.Sprintf("[Documentation](%s)", docs)}
	for _, item := range s.Nav {
		href, ok := links[item.Key]
		if !ok {
			continue
		}
		parts = append(parts, fmt.Sprintf("[%s](%s)", item.Label.For(lang), href))
	}
	return strings.Join(parts, " · ")
}

func languageSwitch(lang string, inDocs bool) string {
	if lang == "fr" {
		if inDocs {
			return "[English](../)"
		}
		return "[English](README.md)"
	}
	if inDocs {
		return "[Français](fr/)"
	}
	return "[Français](docs/fr/index.md)"
}

func sourceLabel(lang string) string {
	if lang == "fr" {
		return "Code source"
	}
	return "Source"
}

// runsTable renders the "what runs where" table from the declared columns and
// rows.
func (s Site) runsTable(lang string) string {
	var out strings.Builder
	out.WriteString("|")
	for _, column := range s.Runs.Columns {
		out.WriteString(" ")
		out.WriteString(column.For(lang))
		out.WriteString(" |")
	}
	out.WriteString("\n|")
	for range s.Runs.Columns {
		out.WriteString(" --- |")
	}
	out.WriteString("\n")
	for _, row := range s.Runs.Rows {
		out.WriteString("|")
		for _, cell := range row.Cells {
			out.WriteString(" ")
			out.WriteString(cell.For(lang))
			out.WriteString(" |")
		}
		out.WriteString("\n")
	}
	return out.String()
}
